import{D,ITEMS}from'./story.mjs';
const $=s=>document.querySelector(s);export function createPuzzles(api){const{get,commit,say,open,close,notify,fx,glitch,readItem}=api;
function keypad(){let code='';open(`<span class="overline">工具柜 / 离线密码锁</span><h2>他最后一次到岗</h2><div class="keypad-wrap"><div><div class="note-sheet"><small>终端缓存</small>“柜子留给你。<br>密码是我最后一次到岗的时间。”</div><p class="muted">四位数字。考勤记录已经收进手记。</p><button class="btn" id="clock-note">查看考勤记录</button><p class="feedback" id="key-feedback"></p></div><div><div class="readout" id="code" aria-live="polite">_ _ _ _</div><div class="keypad">${['1','2','3','4','5','6','7','8','9','清除','0','确认'].map(k=>`<button data-key="${k}">${k}</button>`).join('')}</div></div></div>`,()=>{const update=()=>$('#code').textContent=code.padEnd(4,'_').split('').join(' ');const press=k=>{fx();if(k==='清除')code='';else if(k==='确认'){if(code.length<4){$('#key-feedback').textContent='还需要四位完整数字。';return;}if(commit('locker',code)){fx('success');close();say(D.locker);return;}commit('mistake');$('#key-feedback').textContent='锁没有打开。是“到岗”，不是系统里的离职日期。';code='';fx('error');}else if(code.length<4)code+=k;update();};document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>press(b.dataset.key));$('#clock-note').onclick=()=>$('#key-feedback').textContent=ITEMS.clock.text;const key=e=>{if(/^[0-9]$/.test(e.key))press(e.key);if(e.key==='Backspace'){code=code.slice(0,-1);update();}if(e.key==='Enter'){e.preventDefault();press('确认');}};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key);});}
function camera(){let aim=42,focus=25;open(`<span class="overline">机械取景 / 最后一张胶片</span><h2>对准 C-07，稳住焦点</h2><p class="panel-intro">让右侧配电柜完整进入取景框，再调节焦距使细节清晰。</p><div class="camera-view"><img src="assets/server-future.webp" alt="机房右侧的配电柜 C-07"><div class="reticle"></div><span class="camera-reading">ISO 400 / 1:125 / 01</span></div><div class="slider-row"><label for="aim">构图</label><input id="aim" aria-label="取景位置" type="range" min="20" max="88" value="42"><output id="aim-output">42</output></div><div class="slider-row"><label for="focus">焦距</label><input id="focus" aria-label="调节焦距" type="range" min="0" max="100" value="25"><output id="focus-output">25</output></div><p class="feedback" id="camera-feedback">配电柜还没有完整进入取景框。</p><div class="actions"><button class="btn primary" id="shutter">按下快门</button></div>`,()=>{const update=()=>{$('.reticle').style.left=aim+'%';$('.camera-view').style.setProperty('--focus-blur',Math.abs(focus-63)/8+'px');$('#aim-output').textContent=aim;$('#focus-output').textContent=focus;$('#camera-feedback').textContent=Math.abs(aim-72)>6?'配电柜还没有完整进入取景框。':Math.abs(focus-63)>7?'构图合适。转动焦距，直到线缆细节变清楚。':'影像清晰。可以按下快门。';};$('#aim').oninput=e=>{aim=+e.target.value;update();};$('#focus').oninput=e=>{focus=+e.target.value;update();};update();$('#shutter').onclick=()=>{if(Math.abs(aim-72)>6||Math.abs(focus-63)>7){fx('error');$('#camera-feedback').textContent='先确认构图与焦距。别浪费最后一张胶片。';return;}if(commit('photo')){fx('shutter');$('#flash').classList.remove('fire');void $('#flash').offsetWidth;$('#flash').classList.add('fire');close();say(D.photo);}};});}
function logs(){open(`<span class="overline">归档终端 / 维护员 061</span><h2>哪条记录与你的记忆矛盾？</h2><p class="panel-intro">你清楚地记得自己在 01:40 签退。纸质工单上又留下了你的笔迹。选择需要追查的一条记录。</p><div class="record-grid"><button class="record" data-record="exit"><time>01:40</time><span>维护员 061 签退<br><small>出口闸机 / 本人确认</small></span></button><button class="record" data-record="signature"><time>02:17</time><span>C-07 辅助支路接入<br><small>执行与签名：维护员 061</small></span></button><button class="record" data-record="purge"><time>02:19</time><span>清理当班影像<br><small>执行：系统自动归档</small></span></button></div><p class="feedback" id="logs-feedback">纸质工单：02:17 / 辅助支路接入 / 执行人 061。</p>`,()=>document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{if(commit('logs',b.dataset.record)){fx('success');close();glitch();say(D.logs);}else{commit('mistake');fx('error');$('#logs-feedback').textContent=b.dataset.record==='exit'?'这条记录与你的记忆一致。问题在于签退后还有谁用了你的身份。':'清理影像很可疑，但它不能解释工单上为什么有你的签名。';}}));}
function develop(){let step=0,exposure=false,start=0,raf=0,timer=0;const labels=['胶片','曝光','显影','停显','定影'];open(`<span class="overline">旧测试室 / 信号隔绝</span><h2>不要急着看见答案</h2><p class="panel-intro" id="dev-instruction">先把胶片装入密封罐处理。操作依据放在手册里。</p><div class="step-trail">${labels.map((l,i)=>`<span id="dev-step-${i}">${String(i+1).padStart(2,'0')} ${l}</span>`).join('')}</div><div class="tray"><img src="assets/photo.png" alt="等待显影的相纸"></div><div class="exposure-meter"><div class="sweet"></div><i id="exposure-fill"></i></div><p class="feedback" id="dev-feedback">放大曝光目标约 3 秒。过度曝光可以重试。</p><div class="darkroom-tools"><button class="btn" id="tank">处理胶片</button><button class="btn" id="expose" disabled>开始曝光</button><button class="btn" data-bath="2" disabled>显影液</button><button class="btn" data-bath="3" disabled>停显液</button><button class="btn" data-bath="4" disabled>定影液</button></div>`,()=>{let waiting=false;const finishExposure=()=>{if(!exposure)return;exposure=false;cancelAnimationFrame(raf);$('.tray').classList.remove('exposing');const seconds=(performance.now()-start)/1000;if(seconds>=2.7&&seconds<=3.6){step=2;$('#dev-step-1').classList.add('done');$('#expose').disabled=true;document.querySelectorAll('[data-bath]').forEach(b=>b.disabled=false);$('#dev-feedback').textContent='潜影已形成。依照手册，将相纸放入正确的药液。';$('#dev-instruction').textContent='画面尚未出现。需要让影像逐步显现。';fx('success');}else{commit('mistake');$('#expose').textContent='重新曝光';$('#dev-feedback').textContent=seconds<2.7?'曝光不足。换一张相纸，接近 3 秒时停止。':'曝光过度。换一张相纸，再试一次。';fx('error');}};const update=()=>{if(!exposure)return;const t=(performance.now()-start)/1000;$('#exposure-fill').style.width=Math.min(t/6*100,100)+'%';$('#dev-feedback').textContent=`曝光中 ${t.toFixed(1)} 秒 · 再点一次停止`;if(t>=6){finishExposure();return;}raf=requestAnimationFrame(update);};$('#tank').onclick=()=>{if(waiting)return;waiting=true;$('#tank').disabled=true;$('#dev-feedback').textContent='密封罐缓慢倒转。里面传来液体流动的声音。';fx('door');timer=setTimeout(()=>{step=1;waiting=false;$('#dev-step-0').classList.add('done');$('#expose').disabled=false;$('#dev-instruction').textContent='底片已准备好。控制放大机曝光时长。';$('#dev-feedback').textContent='点击开始曝光，约 3 秒时再次点击停止。';},1100);};$('#expose').onclick=()=>{if(exposure){finishExposure();return;}exposure=true;start=performance.now();$('#expose').textContent='停止曝光';$('.tray').classList.add('exposing');update();};document.querySelectorAll('[data-bath]').forEach(b=>b.onclick=()=>{if(waiting)return;const bath=+b.dataset.bath;if(bath!==step){commit('mistake');fx('error');$('#dev-feedback').textContent='顺序不对。先让影像显现，再停止反应，最后固定。';return;}waiting=true;b.disabled=true;$('#dev-step-'+step).classList.add('done');if(step===2){$('.tray').style.setProperty('--photo-opacity',1);$('#dev-feedback').textContent='影像慢慢加深。右下方，出现了不该存在的东西。';}else $('#dev-feedback').textContent=step===3?'反应正在停止。':'照片正在固定。';timer=setTimeout(()=>{step++;waiting=false;if(step===5){commit('develop');fx('success');close();say(D.developed);}else $('#dev-feedback').textContent=step===3?'影像出现了。下一步需要停止反应。':'最后一步，让照片能够在普通光线下保存。';},step===2?2900:800);});return()=>{cancelAnimationFrame(raf);clearTimeout(timer);};});}
function photo(){open(`<span class="overline">胶片记录 / C-07</span><h2>熟悉的，和多出来的</h2><div class="photo-desk"><div class="photo-area" id="photo-area"><img src="assets/photo.png" alt="配电箱黑白照片，上方诊断单元，下方线路与模块"><button class="photo-clue ${get().clues.includes('mark')?'found':''}" data-clue="mark" aria-label="检查线束固定点"></button><button class="photo-clue ${get().clues.includes('module')?'found':''}" data-clue="module" aria-label="检查右下模块"></button></div><div><p class="panel-intro">点击照片中的异常细节。线索没有被标出，需要你自己观察。</p><div class="observation ${get().clues.includes('mark')?'found':''}">${get().clues.includes('mark')?'已确认 / 我的接线习惯':'待确认 / 熟悉的施工细节'}</div><div class="observation ${get().clues.includes('module')?'found':''}">${get().clues.includes('module')?'已确认 / 被隐藏的模块':'待确认 / 肉眼看不到的东西'}</div><p class="feedback" id="photo-feedback">${get().clues.length} / 2 处已确认</p><div class="actions"><button class="btn" id="photo-close">收好照片</button></div></div></div>`,()=>{$('#photo-close').onclick=close;$('#photo-area').onclick=e=>{const clue=e.target.closest('[data-clue]');if(!clue){$('#photo-feedback').textContent='上方诊断单元没有变化。沿下方线束继续观察。';return;}const id=clue.dataset.clue;commit('clue',id);fx('paper');close();say(D[id]);};});}
function deduction(){const s=get(),ready=s.clues.length===2&&s.flags.files&&s.flags.logs;open(`<span class="overline">证据推理 / 安全区域</span><h2>哪种解释，同时说得通？</h2><div class="deduction-evidence"><span>${s.clues.length===2?'✓':'○'} 胶片中的异常</span><span>${s.flags.files?'✓':'○'} 本人的签名</span><span>${s.flags.logs?'✓':'○'} 签退后的工单</span></div><p class="panel-intro">${ready?'你接过那组线，却不记得。照片拍到的设备，肉眼却看不到。找出能同时解释三条证据的判断。':'还缺少能够互相印证的证据。照片需要检查两处；纸质工单和终端记录在封存档案室。'}</p>${ready?'<div class="answers"><button class="btn" data-answer="camera">相机损坏，照片出现重影。</button><button class="btn" data-answer="forged">有人伪造了我的签名和线路。</button><button class="btn" data-answer="perception">系统修改了感知，并隐藏了我的部分操作记忆。</button></div>':''}<p id="deduction-feedback" class="feedback"></p>`,()=>document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(commit('deduce',b.dataset.answer)){fx('success');close();say(D.deduced);}else{commit('mistake');fx('error');$('#deduction-feedback').textContent=b.dataset.answer==='camera'?'相机故障无法解释纸质签名和签退以后的施工。':'签名伪造无法解释为什么肉眼看不到照片中的模块。';}}));}
function circuit(){let angles=[1,0,3],traced=false;open(`<span class="overline">C-07 / 手动隔离前核对</span><h2>用自己的接线习惯，找到出口</h2><p class="panel-intro">这是线路草图。点击 A、B、C 旋转接点，还原从左侧电源到右侧模块的路径。上方主干保持独立。</p><div class="wiring"><div class="main-rail"><span>主干 / 诊断 01</span><span>诊断 02</span><span>诊断 03</span></div><div class="circuit-diagram" style="position:relative;aspect-ratio:480/230"><svg viewBox="0 0 480 230" style="width:100%;height:100%;stroke:#61737b;stroke-width:3"><path d="M20 60H110M140 90V145M170 175H290M320 145V60H450"/><text x="5" y="35" style="fill:#d6b179;stroke:none;font-size:14px">供电</text><text x="385" y="35" style="fill:#d6b179;stroke:none;font-size:14px">模块</text></svg>${[[29.17,26.09],[29.17,76.09],[66.67,76.09]].map(([x,y],i)=>`<button data-wire="${i}" aria-label="旋转接点${'ABC'[i]}" style="position:absolute;left:${x}%;top:${y}%;width:16%;height:34%;transform:translate(-50%,-50%);border:1px solid #6a7a8066;background:#101d26;padding:4px"><svg id="wire-${i}" viewBox="0 0 60 60" style="width:100%;height:100%;stroke:#d6b179;stroke-width:3"><path d="M0 30H30V60"/><circle cx="30" cy="30" r="3"/></svg><small style="position:absolute;right:4px;top:0;font:11px monospace;color:#a9b6bd">${'ABC'[i]}</small></button>`).join('')}</div></div><p class="feedback" id="wire-feedback">旋转的是草图接点，不会改变实际设备。</p><div class="actions"><button class="btn" id="trace">核对通路</button><button class="btn primary" id="isolate" disabled>扳下隔离器</button><button class="btn" id="wire-photo">查看参考照片</button></div><div id="wire-reference" hidden><img src="assets/photo.png" alt="线路参考照片" style="display:block;max-height:250px;max-width:100%;margin:20px auto"></div>`,()=>{const paint=()=>angles.forEach((a,i)=>$('#wire-'+i).style.transform=`rotate(${a*90}deg)`);paint();document.querySelectorAll('[data-wire]').forEach(b=>b.onclick=()=>{if(traced)return;const i=+b.dataset.wire;angles[i]=(angles[i]+1)%4;paint();fx();});$('#trace').onclick=()=>{if(angles.every((a,i)=>a===[0,2,1][i])){traced=true;$('#isolate').disabled=false;$('#trace').disabled=true;$('#wire-feedback').textContent='支路已确认。左下隔离器只影响隐藏模块，诊断主干保持运行。';fx('success');}else{commit('mistake');fx('error');$('#wire-feedback').textContent='仍有断开的接点。每个接点的两个端口，都要接上相邻灰线。';}};$('#wire-photo').onclick=()=>{$('#wire-reference').hidden=!$('#wire-reference').hidden;};$('#isolate').onclick=()=>{if(!traced)return;if(commit('isolate')){fx('door');close();glitch();say(D.isolated);}};});}
return{keypad,camera,logs,develop,photo,deduction,circuit};}
